// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint48 warpTime) public {
        value = bound(value, 10 ether, 10 ether);
        vm.assume(warpTime > 0);
        vm.deal(address(this), value);

        vm.warp(warpTime);
        (bool ok1, ) = address(c).call{value: value}("");
        require(ok1, "first call failed");
        uint256 firstPastBlockTime = c.pastBlockTime();

        vm.deal(address(this), value);
        (bool ok2, ) = address(c).call{value: value}("");

        if (ok2) {
            assertEq(c.pastBlockTime(), block.timestamp, "pastBlockTime must equal current timestamp after success");
        } else {
            assertEq(c.pastBlockTime(), firstPastBlockTime, "pastBlockTime unchanged on revert");
        }
    }
}
